    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=0.8,
    lambda_cut=3.5,
    opt_shots=1024,
    final_shots=4096,
    maxiter=100,
    n_repro_runs=3,
    seed=42,
):
