    Solve balanced minimum cut with hybrid, warm-start QAOA.

    The classical seed is obtained independently by spectral bisection. QAOA
    samples and balance-preserving local search can improve this incumbent.
    The known reference is used only for evaluation, never for initialization,
    optimization, candidate selection, or stopping.

    The diagonal objective is
        lambda_cut * cut
        + lambda_balance * ((sum_i Z_i)**2 - (n mod 2)).
    Its balance penalty is zero for precisely the allowed bisection sizes.

    The warm-start mixer has the initial product state as an eigenstate.
    Reported graph metrics describe the selected feasible partition, not an
    expectation over infeasible quantum samples. Aer simulation is exponential
    in n; this implementation is intended for small graphs such as n=11.
    """
    started = time.perf_counter()
    vertices = list(graph_vertices)
    n = len(vertices)

    if n < 2 or len(set(vertices)) != n:
        raise ValueError("Provide at least two distinct, hashable vertices.")

    integer_arguments = {
        "p_layers": p_layers,
        "opt_shots": opt_shots,
        "final_shots": final_shots,
        "maxiter": maxiter,
        "n_repro_runs": n_repro_runs,
    }
    for name, value in integer_arguments.items():
        if not isinstance(value, (int, np.integer)) or value < 1:
            raise ValueError(f"{name} must be a positive integer.")

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")
    if not isinstance(seed, (int, np.integer)) or seed < 0:
        raise ValueError("seed must be a nonnegative integer.")

    graph = nx.Graph()
    graph.add_nodes_from(vertices)
    vertex_set = set(vertices)
    for edge in graph_edges:
        if len(edge) != 2:
            raise ValueError("Each edge must contain exactly two vertices.")
        u, v = edge
        if u not in vertex_set or v not in vertex_set:
            raise ValueError("An edge refers to an unknown vertex.")
        if u == v:
            raise ValueError("Self-loops are not supported.")
        graph.add_edge(u, v)

    reference_a, _ = _parse_reference_partition(
        vertices, known_reference_partition
    )
    reference_cut = sum(
        (u in reference_a) != (v in reference_a) for u, v in graph.edges()
    )

    index = {vertex: i for i, vertex in enumerate(vertices)}
    edge_indices = {
        tuple(sorted((index[u], index[v]))) for u, v in graph.edges()
    }

    # Integer bit i corresponds to qubit i and graph_vertices[i].
    dimension = 1 << n
    states = np.arange(dimension, dtype=np.int64)
    weights = np.fromiter(
        (mask.bit_count() for mask in range(dimension)),
        dtype=np.int64,
        count=dimension,
    )
    cut_table = np.zeros(dimension, dtype=np.int64)
    for i, j in edge_indices:
        cut_table += ((states >> i) ^ (states >> j)) & 1

    feasible = (weights == n // 2) | (weights == (n + 1) // 2)
    energies = (
        lambda_cut * cut_table
        + lambda_balance * ((n - 2 * weights) ** 2 - n % 2)
    )
    warm_mask = _spectral_warm_start(graph, vertices, cut_table)

    # A soft rather than computational-basis initialization permits exploration.
    epsilon = 0.10
    probabilities = np.array(
        [
            1.0 - epsilon if (warm_mask >> i) & 1 else epsilon
            for i in range(n)
        ]
    )
    initial_angles = 2.0 * np.arcsin(np.sqrt(probabilities))
    gammas = ParameterVector("gamma", int(p_layers))
    betas = ParameterVector("beta", int(p_layers))
    phase_scale = max(lambda_cut, 4.0 * lambda_balance, 1.0)

    circuit = QuantumCircuit(n)
    for i, angle in enumerate(initial_angles):
        circuit.ry(float(angle), i)

    for layer in range(int(p_layers)):
        for i in range(n):
            for j in range(i + 1, n):
                # RZZ(theta) = exp(-i theta ZiZj / 2).
                coefficient = 4.0 * lambda_balance
                if (i, j) in edge_indices:
                    coefficient -= lambda_cut
                if coefficient != 0:
                    circuit.rzz(
                        gammas[layer] * (coefficient / phase_scale), i, j
                    )

        for i, angle in enumerate(initial_angles):
            # exp[-i beta (sin(angle) X + cos(angle) Z)].
            circuit.ry(-float(angle), i)
            circuit.rz(2.0 * betas[layer], i)
            circuit.ry(float(angle), i)

    circuit.measure_all()
    backend = AerSimulator(method="statevector", max_parallel_threads=1)
    template = transpile(
        circuit,
        backend,
        optimization_level=1,
        seed_transpiler=int(seed) % (2**32 - 1),
    )

    def sample(parameters, shots, simulator_seed):
        assignments = {
            gammas[layer]: float(parameters[layer])
            for layer in range(int(p_layers))
        }
        assignments.update(
            {
                betas[layer]: float(parameters[int(p_layers) + layer])
                for layer in range(int(p_layers))
            }
        )
        bound = template.assign_parameters(assignments, inplace=False)
        result = backend.run(
            bound,
            shots=int(shots),
            seed_simulator=int(simulator_seed),
        ).result()
        return {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in result.get_counts().items()
        }

    seed_sequences = np.random.SeedSequence(int(seed)).spawn(int(n_repro_runs))
    run_records = []
    run_masks = []

    for sequence in seed_sequences:
        run_seed = int(sequence.generate_state(1, dtype=np.uint32)[0])
        rng = np.random.default_rng(run_seed)
        optimization_seed = int(rng.integers(1, 2**31 - 1))
        final_seed = int(rng.integers(1, 2**31 - 1))
        observed_feasible = set()
        best_parameters = np.zeros(2 * int(p_layers))
        best_expectation = float("inf")
        evaluation_count = 0

        def absorb(counts):
            for mask in counts:
                if feasible[mask]:
                    observed_feasible.add(_canonical_mask(mask, n))

        def objective(parameters):
            nonlocal best_parameters, best_expectation, evaluation_count
            # Fixed random numbers within a run reduce optimization noise.
            counts = sample(parameters, opt_shots, optimization_seed)
            absorb(counts)
            expectation = sum(
                float(energies[mask]) * count
                for mask, count in counts.items()
            ) / sum(counts.values())
            evaluation_count += 1
            if expectation < best_expectation:
                best_expectation = float(expectation)
                best_parameters = np.array(parameters, dtype=float, copy=True)
            return expectation / phase_scale

        # Include the unmodified warm-start distribution as a parameter candidate.
        objective(best_parameters)
        initial_parameters = np.concatenate(
            (
                rng.uniform(-0.35, 0.35, int(p_layers)),
                rng.uniform(-0.35, 0.35, int(p_layers)),
            )
        )
        optimization = minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={
                "maxiter": int(maxiter),
                "rhobeg": 0.25,
                "tol": 1e-3,
            },
        )

        final_counts = sample(best_parameters, final_shots, final_seed)
        absorb(final_counts)

        # Classical postprocessing never uses the reference partition.
        candidates = sorted(
            observed_feasible,
            key=lambda mask: (int(cut_table[mask]), mask),
        )[:32]
        polished = {warm_mask}
        polished.update(
            _polish_balanced_partition(mask, n, cut_table)
            for mask in candidates
        )
        selected = min(
            polished, key=lambda mask: (int(cut_table[mask]), mask)
        )
        selected_cut = int(cut_table[selected])
        run_masks.append(selected)

        total_final = sum(final_counts.values())
        feasible_final = sum(
            count for mask, count in final_counts.items() if feasible[mask]
        )
        matching_cut_final = sum(
            count
            for mask, count in final_counts.items()
            if feasible[mask] and int(cut_table[mask]) == selected_cut
        )
        run_records.append(
            {
                "seed": run_seed,
                "cut_size": selected_cut,
                "approximation_ratio": _approximation_ratio(
                    reference_cut, selected_cut
                ),
                "best_sampled_feasible_cut": (
                    min(int(cut_table[mask]) for mask in observed_feasible)
                    if observed_feasible
                    else None
                ),
                "final_feasible_probability": feasible_final / total_final,
                "final_selected_cut_probability": matching_cut_final / total_final,
                "optimized_penalized_expectation": best_expectation,
                "objective_evaluations": evaluation_count,
                "optimizer_success": bool(optimization.success),
                "gamma": best_parameters[:int(p_layers)].tolist(),
                "beta": best_parameters[int(p_layers):].tolist(),
            }
        )

    selected = min(
        run_masks, key=lambda mask: (int(cut_table[mask]), mask)
    )
    group_0 = [v for i, v in enumerate(vertices) if not ((selected >> i) & 1)]
    group_1 = [v for i, v in enumerate(vertices) if (selected >> i) & 1]
    selected_cut = int(cut_table[selected])

    if graph.number_of_edges():
        modularity_score = float(
            nx.algorithms.community.quality.modularity(
                graph, [set(group_0), set(group_1)], weight=None
            )
        )
    else:
        modularity_score = 0.0

    volume_0 = sum(graph.degree(vertex) for vertex in group_0)
    volume_1 = sum(graph.degree(vertex) for vertex in group_1)
    normalized_cut_score = (
        selected_cut / volume_0 if volume_0 else 0.0
    ) + (
        selected_cut / volume_1 if volume_1 else 0.0
    )

    # A 6/5 split of 11 vertices receives the maximum balance score, 1.
    excess_imbalance = abs(len(group_0) - len(group_1)) - n % 2
    balance_constraint_score = 1.0 - excess_imbalance / (n - n % 2)
    run_cuts = np.array([record["cut_size"] for record in run_records], dtype=float)

    return {
        "modularity_score": modularity_score,
        "normalized_cut_score": float(normalized_cut_score),
        "balance_constraint_score": float(balance_constraint_score),
        "approximation_ratio": _approximation_ratio(reference_cut, selected_cut),
        "runtime": float(time.perf_counter() - started),
        "reproducibility": {
            "n_runs": int(n_repro_runs),
            "mean_cut_size": float(run_cuts.mean()),
            "std_cut_size": float(run_cuts.std()),
            "reference_target_success_rate": float(
                np.mean(run_cuts <= reference_cut)
            ),
            "partition_agreement_rate": float(
                sum(mask == selected for mask in run_masks) / len(run_masks)
            ),
            "runs": run_records,
        },
        "partition": {"group_0": group_0, "group_1": group_1},
        "group_sizes": [len(group_0), len(group_1)],
        "cut_size": selected_cut,
        "reference_cut": int(reference_cut),
        "warm_start_cut_size": int(cut_table[warm_mask]),
        "method": "spectral-warm-start QAOA with balanced local postprocessing",
    }


