        ("R1", "R2"),
        ("R2", "R3"),
        ("R3", "R4"),
        ("R4", "R5"),
        ("R5", "R0"),
        ("R0", "R2"),
        ("R1", "R3"),
        ("P0", "P1"),
        ("P1", "P2"),
        ("P2", "P3"),
        ("P3", "P4"),
        ("P4", "P0"),
        ("P0", "P2"),
        ("R1", "P2"),
        ("R4", "P0"),
    ]
    known_reference_partition = {
        "Team R": ["R0", "R1", "R2", "R3", "R4", "R5"],
